def compute(vars):
    earnings = vars["v1"]
    segment_net_sales = vars["v2"]
    if segment_net_sales == 0:
        return None
    value = earnings / segment_net_sales * 100
    return {
        "value": value,
        "trace": {
            "operating_earnings": earnings,
            "segment_net_sales": segment_net_sales,
            "ratio": earnings / segment_net_sales,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
